diff --git a/test/sdk.test.js b/test/sdk.test.js
new file mode 100644
index 0000000..e42e75e
--- /dev/null
+++ b/test/sdk.test.js
@@ -0,0 +1,53 @@
+'use strict';
+// Drives the real call sites (api/ai.js and mcp/insights.js) with a stubbed fetch.
+const assert = require('assert');
+const Module = require('module');
+
+const seen = [];
+const stubFetch = async (url, init) => {
+  seen.push({ url: String(url), body: JSON.parse(String(init.body)), headers: new Headers(init.headers) });
+  return new Response(
+    JSON.stringify({
+      id: 'm', type: 'message', role: 'assistant', model: 'claude-opus-5',
+      content: [{ type: 'text', text: 'hi' }], stop_reason: 'end_turn', stop_sequence: null,
+      usage: { input_tokens: 1, output_tokens: 1 },
+    }),
+    { headers: { 'content-type': 'application/json' } }
+  );
+};
+
+// Inject fetch into every Anthropic client the app builds.
+const origLoad = Module._load;
+Module._load = function (request, ...rest) {
+  const mod = origLoad.call(this, request, ...rest);
+  if (request === '@anthropic-ai/sdk') {
+    const Base = mod.default || mod;
+    const Wrapped = function (opts) { return new Base({ ...(opts || {}), fetch: stubFetch }); };
+    Wrapped.prototype = Base.prototype;
+    return Wrapped;
+  }
+  return mod;
+};
+
+(async () => {
+  process.env.ANTHROPIC_API_KEY = 'dummy';
+  const handler = require('../api/ai.js');
+  const { generateInsights } = require('../mcp/insights.js');
+
+  let out;
+  const res = { status(c) { this.code = c; return this; }, json(o) { out = o; return this; } };
+  await handler({ method: 'POST', body: { messages: [{ role: 'user', content: 'x' }], temperature: 0.9 } }, res);
+  assert.strictEqual(res.code, 200, JSON.stringify(out));
+  assert.strictEqual(out.choices[0].message.content, 'hi');
+
+  const r = await generateInsights({ labels: ['a'], series: [1] });
+  assert.strictEqual(r.text, 'hi');
+
+  assert.strictEqual(seen.length, 2);
+  for (const s of seen) {
+    assert.strictEqual(s.headers.get('anthropic-version'), '2026-10-21');
+    for (const k of ['temperature', 'top_p', 'top_k']) assert(!(k in s.body), k);
+    assert.strictEqual(s.body.model, 'claude-opus-5');
+  }
+  console.log('ok');
+})().catch((e) => { console.error(e); process.exit(1); });
